// 新雇用段逐字段严格保存；不修改原estate或local_economy的持久布局。
#pragma once
#include "estate_employment.hpp"
#include "../../local_economy/local_economy_codec_detail.hpp"
namespace hanmo::resident::dynamic_economy_codec {
template<class A> void record(A& a,EstateEmploymentPolicy& v){a("id",v.id);a("estate_id",v.estate_id);a("job",v.job);a("rate_profile",v.rate_profile);a("offer_dialogue_id",v.offer_dialogue_id);a("offer_node_id",v.offer_node_id);a("worker_dialogue_id",v.worker_dialogue_id);a("worker_node_id",v.worker_node_id);a("service_ticks",v.service_ticks);a("offer_valid_ticks",v.offer_valid_ticks);a("provider_offer_dialogue_id",v.provider_offer_dialogue_id);a("provider_offer_node_id",v.provider_offer_node_id);a("provider_reply_dialogue_id",v.provider_reply_dialogue_id);a("provider_reply_node_id",v.provider_reply_node_id);a("provider_reply_decision",v.provider_reply_decision);}
template<class A> void record(A& a,EstateEmploymentCatalog& v){a("version",v.version);a("policies",v.policies);}
template<class A> void record(A& a,EstateEmploymentTerms& v){a("policy_id",v.policy_id);a("estate_id",v.estate_id);a("employer_actor_id",v.employer_actor_id);a("worker_actor_id",v.worker_actor_id);a("job",v.job);a("rate_profile",v.rate_profile);a("payer_wallet_id",v.payer_wallet_id);a("payee_wallet_id",v.payee_wallet_id);a("wage_numerator",v.wage_numerator);a("wage_denominator",v.wage_denominator);a("service_ticks",v.service_ticks);a("offer_expires_tick",v.offer_expires_tick);a("reservation_cap",v.reservation_cap);}
template<class A> void record(A& a,EstateEmploymentMeeting& v){a("actor_id",v.actor_id);a("provider_actor_id",v.provider_actor_id);a("session_id",v.session_id);a("dialogue_id",v.dialogue_id);a("node_id",v.node_id);a("node_kind",v.node_kind);a("place_id",v.place_id);a("speaker_actor_id",v.speaker_actor_id);}
template<class A> void record(A& a,EstateEmploymentContract& v){a("id",v.id);a("status",v.status);a("acceptance_fact_id",v.acceptance_fact_id);a("terminal_fact_id",v.terminal_fact_id);a("obligation_id",v.obligation_id);a("terms",v.terms);a("offered_at",v.offered_at);a("offered_tick",v.offered_tick);a("accepted_tick",v.accepted_tick);a("through_tick",v.through_tick);a("offer_from_provider",v.offer_from_provider);}
template<class A> void record(A& a,EstateEmploymentDecisionFact& v){a("id",v.id);a("contract_id",v.contract_id);a("actor_id",v.actor_id);a("decision",v.decision);a("tick",v.tick);a("meeting",v.meeting);a("terminal_arrear_id",v.terminal_arrear_id);a("provider_declared",v.provider_declared);a("death_fact_id",v.death_fact_id);}
template<class A> void record(A& a,EstateEmploymentService& v){a("id",v.id);a("contract_id",v.contract_id);a("production_fact_id",v.production_fact_id);a("arrear_id",v.arrear_id);a("tick",v.tick);a("remainder_before",v.remainder_before);a("remainder_after",v.remainder_after);}
template<class A> void record(A& a,EstateEmploymentState& v){a("version",v.version);a("initialized_tick",v.initialized_tick);a("last_step_tick",v.last_step_tick);a("contracts",v.contracts);a("decisions",v.decisions);a("services",v.services);}
}
